tools.json:
{
  "type": "function",
  "function": {
    "name": "decide_proactive_message",
    "description": "Decide whether the server should start one proactive conversation.",
    "parameters": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "action",
        "topic",
        "tone",
        "safe_fact_ids",
        "reason"
      ],
      "properties": {
        "action": {
          "type": "string",
          "enum": [
            "send",
            "skip"
          ]
        },
        "topic": {
          "type": "string",
          "enum": [
            "casual_check_in",
            "share_presence",
            "follow_up_past_topic",
            "scheduled_reminder"
          ]
        },
        "tone": {
          "type": "string",
          "enum": [
            "gentle",
            "playful",
            "calm",
            "encouraging",
            "warm"
          ]
        },
        "safe_fact_ids": {
          "type": "array",
          "maxItems": 5,
          "items": {
            "type": "string",
            "enum": [
              "current_local_time",
              "current_day_period",
              "conversation_gap",
              "last_user_message",
              "task_intent"
            ]
          }
        },
        "reason": {
          "type": "string",
          "minLength": 1,
          "maxLength": 160
        }
      }
    }
  }
}
